INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('dec-001','decision','acme-api','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"summary": "Serve the public API from a single edge Worker rather than a regional cluster", "problem": "Latency from APAC was over 400ms and the regional fleet cost more than the traffic justified.", "why_chosen": "Edge execution puts the handler in the same PoP as the client, and the workload is stateless RPC against a replicated store, so there is nothing to keep warm regionally.", "what_we_tried": "A second region in ap-southeast. It halved APAC latency, doubled the bill, and did nothing for South America.", "tradeoffs": "No long-running connections, and a memory ceiling we now design around.", "alternatives": [{"option": "Regional Kubernetes fleet", "reason_rejected": "Cost scaled with regions rather than with traffic"}, {"option": "CDN caching in front of the old fleet", "reason_rejected": "Responses are per-user, so the hit rate would be near zero"}], "constraints_created": ["Never block the handshake on a database round-trip"], "tags": ["architecture", "latency", "edge"], "origin": "user"}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('con-001','constraint','acme-api','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"rule": "Never block the handshake on a database round-trip", "reason": "A cold start that waits on the database is slow enough for a reconnecting client to time out and retry, which multiplies the load that caused it.", "scope": "src/index.ts", "hardness": "absolute", "enforced_by": "test/cold-start.test.ts", "tags": ["performance", "startup"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('pipe-001','pipeline','acme-api','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"name": "release", "purpose": "Tag, build and promote a release with a reversible step at each stage.", "steps": [{"order": 1, "action": "tag the release commit"}, {"order": 2, "action": "build and publish the image"}, {"order": 3, "action": "promote to staging, run smoke tests"}, {"order": 4, "action": "promote to production"}], "tags": ["release"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('dec-002','decision','billing','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"summary": "Store money as integer minor units, never floats", "problem": "Two invoices reconciled to a one-cent difference that took a day to trace back to float rounding.", "why_chosen": "Integer minor units make every operation exact, and the only conversion is at the display boundary where it is obvious.", "tags": ["money", "correctness"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('con-002','constraint','billing','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"rule": "Every webhook handler must be idempotent on the event id", "reason": "The provider retries on any non-2xx, including timeouts we caused, so a handler that is not idempotent will double-charge under exactly the conditions that make it slow.", "scope": "src/webhooks/", "hardness": "absolute", "tags": ["webhooks"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('dec-003','decision','billing','superseded','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z','dec-002','{"summary": "Store money as decimal strings", "problem": "Needed a representation that survived a JSON round-trip.", "tags": ["money"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('dec-004','decision','docs-site','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"summary": "Generate the docs site from source rather than hand-writing pages", "problem": "Three pages disagreed with the code about the same flag and nobody could tell which was right.", "why_chosen": "A generated page cannot drift from what it documents; when it is wrong the source is wrong, and there is one thing to fix.", "tags": ["docs", "drift"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('con-003','constraint','docs-site','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"rule": "Every code sample in the docs must come from a file that is tested", "reason": "A sample that is only prose rots silently, and the first person to notice is a user copying it.", "scope": "docs/", "hardness": "advisory", "tags": ["docs"]}');
INSERT OR REPLACE INTO entries (id,kind,project,status,created_at,updated_at,superseded_by,payload) VALUES ('dec-005','decision','ingest','active','2026-08-06T09:00:00Z','2026-08-06T09:00:00Z',NULL,'{"summary": "Back-pressure the ingest queue instead of buffering in memory", "problem": "A traffic spike filled the buffer and the process was killed, losing everything in it.", "why_chosen": "Refusing work you cannot do is recoverable; accepting work you cannot do is not. The producer already retries.", "tags": ["queues", "reliability"]}');